test('deleted subscriber cannot be resurrected by a stale unsubscribe action',async()=>{const h=await harness();await h.signup();const row=(await(await h.admin({action:'list'})).json()).rows[0];await h.admin({action:'delete',id:row.id,confirm:true});await h.admin({action:'unsubscribe',id:row.id,confirm:true});const list=await(await h.admin({action:'list'})).json();assert.equal(list.total,0);assert(!JSON.stringify([...h.storage.map]).includes(row.email));});
test('Sheet stale status follows actual export and subscriber revisions',async()=>{const h=await harness();let v=await(await h.admin({action:'list'})).json();assert(v.sheetNeedsRefresh);await h.signup();await h.admin({action:'sheet',confirm:true});v=await(await h.admin({action:'list'})).json();assert(!v.sheetNeedsRefresh);assert.equal(v.lastExport.count,1);await h.admin({action:'unsubscribe',id:v.rows[0].id,confirm:true});assert((await(await h.admin({action:'list'})).json()).sheetNeedsRefresh);});
test('cleanup re-arms for a later signup, then stops without touching subscribers',async()=>{const s=new MemoryStorage(),DAY=86400000,first=20000;await s.put('rate:'+first+':hash',{});await s.put('used:'+(first+1)+':nonce',{});await s.put('daily:'+(first+1),1);await s.put('member:stable',{email:'keep@example.org'});const next=await cleanupSubscriptions(s,(first+2)*DAY+2000);assert(next>(first+2)*DAY);assert.equal(await s.get('rate:'+first+':hash'),undefined);assert(await s.get('used:'+(first+1)+':nonce'));assert.equal(await cleanupSubscriptions(s,next),null);assert.equal((await s.list({prefix:'member:'})).size,1);assert.equal(s.map.size,1);});
test('expired Google token and transient Google outage are distinct from a wrong owner',async()=>{const s=new MemoryStorage(),request=req('/admin',{action:'list'},{Authorization:'Bearer short-lived-token'});for(const [external,expected]of [[401,401],[503,503]]){const r=await subscriberWorkspace(request.clone(),s,async()=>Response.json({},{status:external}));assert.equal(r.status,expected);}const r=await subscriberWorkspace(request.clone(),s,async()=>{throw Error('offline')});assert.equal(r.status,503);assert.equal(s.map.size,0);});
